package com.bank.appsec;

import java.util.List;
import java.util.logging.Logger;

public class AppSecScanDemo {
    private static final Logger log = Logger.getLogger(AppSecScanDemo.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — AppSec technique router (loan-origination)");

        // Define the four techniques and WHERE each runs in the SDLC.
        ScanTechnique sast = new ScanTechnique("SAST", "Build (per-commit)",
                "code-level flaws in OUR source: SQLi via concatenation, hardcoded secrets");
        ScanTechnique sca  = new ScanTechnique("SCA", "Build (per-commit + continuous)",
                "known-vulnerable THIRD-PARTY dependencies, license risk");
        ScanTechnique iast = new ScanTechnique("IAST", "Integration testing",
                "real code paths + data flow observed from INSIDE during tests");
        ScanTechnique dast = new ScanTechnique("DAST", "Deployed staging / pre-prod",
                "runtime + config flaws from OUTSIDE: headers, auth, injection");

        // Three findings in this service, each caught by a different technique.
        List<Finding> findings = List.of(
            new Finding("SQL built by string concatenation in LoanRepository", sast),
            new Finding("Transitive log4j-core 2.14 (CVE known-vulnerable)", sca),
            new Finding("Missing Strict-Transport-Security header in prod config", dast)
        );

        for (Finding f : findings) {
            log.warning(() -> "Finding: " + f.description());
            log.info(() -> "  Caught by " + f.caughtBy().name()
                    + " at SDLC stage: " + f.caughtBy().sdlcStage());
            log.info(() -> "  Because " + f.caughtBy().name() + " detects: "
                    + f.caughtBy().detects());
        }

        // Coverage is complete ONLY when all four techniques are in the pipeline.
        boolean iastUsed = true; // integration tests run with the IAST agent
        log.info(() -> "Pipeline coverage: SAST+SCA (build), IAST (" + iastUsed
                + ", tests), DAST (staging) — complementary, no single tool suffices");
    }
}

