class Finding {
    private final String description;
    private final ScanTechnique caughtBy;

    Finding(String description, ScanTechnique caughtBy) {
        this.description = description;
        this.caughtBy = caughtBy;
    }
    String description() { return description; }
    ScanTechnique caughtBy() { return caughtBy; }
}
